const input = $('Tool Trigger: Crear Cita').first().json;
const servicio = $input.first().json;

function parsearFechaColombia(raw) {
  const ahora = new Date();
  const bogotaOffset = -5 * 60;
  const nowBogota = new Date(ahora.getTime() + (ahora.getTimezoneOffset() + bogotaOffset) * 60000);

  if (!raw || typeof raw !== 'string') return new Date();

  let str = raw.trim();

  // 1. Si viene en formato ISO (YYYY-MM-DDTHH:mm...)
  const isoMatch = str.match(/^(\d{4})-(\d{2})-(\d{2})[T ](\d{1,2}):(\d{2})(?::(\d{2}))?(.*)$/);
  if (isoMatch) {
    let [_, y, m, d, hh, mm, ss, tz] = isoMatch;
    let year = parseInt(y);
    if (year < 2026) year = 2026;
    if (!tz || tz.trim() === '') tz = '-05:00';
    return new Date(year + '-' + m + '-' + d + 'T' + hh.padStart(2, '0') + ':' + mm + ':00' + tz);
  }

  // 2. Si viene en lenguaje natural ej: 'mañana a las 3', 'mañana a las 3:00 PM'
  let targetDate = new Date(nowBogota);
  if (/mañana/i.test(str)) {
    targetDate.setDate(targetDate.getDate() + 1);
  }

  let hora = 15; // default 3:00 PM si no se especifica
  let minutos = 0;

  const timeMatch = str.match(/(\d{1,2})(?::(\d{2}))?\s*(am|pm|a\.m\.|p\.m\.)?/i);
  if (timeMatch) {
    let h = parseInt(timeMatch[1]);
    let m = timeMatch[2] ? parseInt(timeMatch[2]) : 0;
    let mer = timeMatch[3] ? timeMatch[3].toLowerCase().replace(/\./g, '') : '';

    if (mer === 'pm' && h < 12) h += 12;
    if (mer === 'am' && h === 12) h = 0;
    if (!mer && h >= 1 && h <= 7) h += 12; // En salon de belleza, 'las 3' son las 15:00

    hora = h;
    minutos = m;
  }

  const y = 2026;
  const m = String(targetDate.getMonth() + 1).padStart(2, '0');
  const d = String(targetDate.getDate()).padStart(2, '0');
  const hh = String(hora).padStart(2, '0');
  const mm = String(minutos).padStart(2, '0');

  return new Date(y + '-' + m + '-' + d + 'T' + hh + ':' + mm + ':00-05:00');
}

const fechaInicio = parsearFechaColombia(input.fecha_hora);
const duracionMs = (servicio.duracion_minutos || 60) * 60 * 1000;
const fechaFin = new Date(fechaInicio.getTime() + duracionMs);

return [{
  json: {
    wa_id: input.wa_id,
    nombre_cliente: input.nombre_cliente || 'Cliente',
    servicio_id: servicio.id,
    nombre_servicio: servicio.nombre,
    precio: servicio.precio_base_cop,
    fecha_inicio: fechaInicio.toISOString(),
    fecha_fin: fechaFin.toISOString(),
    fecha_cita_formateada: fechaInicio.toLocaleString('es-CO', { timeZone: 'America/Bogota' })
  }
}];

const info = $('Calcular Horas y Duración').first().json;

return [{
  json: {
    exito: true,
    mensaje: `¡Listo! Tu cita para ${info.nombre_servicio} ha quedado confirmada para el ${info.fecha_cita_formateada}. Te esperamos en Cra 83 # 09.`
  }
}];

return [{
  json: {
    exito: false,
    mensaje: 'Lo sentimos, ese espacio exacto acaba de ocuparse en la agenda. Por favor indícale al cliente otro horario cercano disponible.'
  }
}];
